export class InMemoryTransport{constructor(){this._messageQueue=[]}static createLinkedPair(){const s=new InMemoryTransport,e=new InMemoryTransport;return s._otherTransport=e,e._otherTransport=s,[s,e]}async start(){for(;this._messageQueue.length>0;){const s=this._messageQueue.shift();this.onmessage?.(s.message,s.extra)}}async close(){const s=this._otherTransport;this._otherTransport=void 0,await(s?.close()),this.onclose?.()}async send(s,e){if(!this._otherTransport)throw new Error("Not connected");this._otherTransport.onmessage?this._otherTransport.onmessage(s,{authInfo:e?.authInfo}):this._otherTransport._messageQueue.push({message:s,extra:{authInfo:e?.authInfo}})}}